#!/bin/sh
# Make the lab's fixture media: tiny synthetic clips with invented
# titles, generated by ffmpeg. No real footage, no real names.
# Usage: ./make-fixtures.sh <output-dir>
set -e
OUT="${1:?usage: make-fixtures.sh <output-dir>}"

mk() { # mk <path> <source-filter>
  mkdir -p "$(dirname "$OUT/$1")"
  ffmpeg -nostdin -v error -y \
    -f lavfi -i "$2" \
    -f lavfi -i "sine=frequency=440:duration=5" \
    -t 5 -c:v libx264 -preset veryfast -crf 28 -pix_fmt yuv420p \
    -c:a aac -shortest "$OUT/$1"
}

mk "movies/The Clockwork Garden (2021)/The Clockwork Garden (2021).mp4" \
   "testsrc2=size=640x360:rate=24:duration=5"
mk "movies/A Field Guide to Clouds (2018)/A Field Guide to Clouds (2018).mp4" \
   "testsrc=size=640x360:rate=24:duration=5"
mk "movies/Harbour Lights (2024)/Harbour Lights (2024).mkv" \
   "smptebars=size=640x360:rate=24:duration=5"
mk "tv/The Walnut Street Bakery/Season 01/The Walnut Street Bakery - s01e01.mp4" \
   "testsrc2=size=640x360:rate=24:duration=5"
mk "tv/The Walnut Street Bakery/Season 01/The Walnut Street Bakery - s01e02.mp4" \
   "testsrc=size=640x360:rate=24:duration=5"
echo "fixtures written under $OUT"
